async function api(path,data){if(data!==undefined&&serviceState.active&&!['login','logout','password/change','maintenance'].includes(path))throw Error('Идёт обновление. Данные не сохранены; повторите после завершения.');if(previewUser&&data!==undefined)throw Error('Режим просмотра: действия недоступны');const r=await fetch('./api/'+path,{method:data===undefined?'GET':'POST',headers:{...(data===undefined?{}:{'Content-Type':'application/json'}),...(previewUser?{'X-MAYAK-View-As':previewUser}:{})},body:data===undefined?undefined:JSON.stringify(data)});const value=await r.json();if(!r.ok){if(r.status===401&&path!=='login'){D=null;login()}throw new Error(value.error||'Ошибка запроса')}return value}
let toastTimer;function toast(t,error=false){const el=$('#toast');el.textContent=t;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5500)}
function rememberGrid(){
 const wrap=$('.time-table')?.closest('.table-wrap');if(page!=='times'||!wrap)return null;
 const active=document.activeElement,key=active?.dataset?.timeInput||active?.dataset?.cellChoice,attribute=active?.dataset?.timeInput?'data-time-input':'data-cell-choice';
 return {x:wrap.scrollLeft,y:wrap.scrollTop,windowY:window.scrollY,key,attribute,selection:attribute==='data-time-input'?[active.selectionStart,active.selectionEnd]:null,dirty:$$('[data-time-input]').filter(i=>i.value!==i.defaultValue).map(i=>[i.dataset.timeInput,i.value])};
}
function restoreGrid(state){if(!state)return;const wrap=$('.time-table')?.closest('.table-wrap');if(!wrap)return;for(const [key,value] of state.dirty){const input=$(`[data-time-input="${key}"]`);if(input)input.value=value;}const active=state.key&&$(`[${state.attribute}="${state.key}"]`);if(active){active.focus({preventScroll:true});if(state.selection)active.setSelectionRange(...state.selection);}wrap.scrollLeft=state.x;wrap.scrollTop=state.y;window.scrollTo({top:state.windowY,behavior:'instant'});}
async function refresh({keepPosition=true}={}){const seq=++refreshSequence;try{const query=new URLSearchParams({period});if(attendanceDate&&attendanceDate.startsWith(period))query.set('attendanceDate',attendanceDate);if(page==='times'&&tab!=='attendance'&&timeRange){query.set('from',timeRange.from);query.set('to',timeRange.to);}const data=await api('bootstrap?'+query);if(seq!==refreshSequence)return;const state=keepPosition?rememberGrid():null;D=data;render();restoreGrid(state);}catch(e){if(D)toast(e.message,true)}}

