  try{if(D.settings.autoLockPreviousMonths&&date.slice(0,7)<D.today.slice(0,7)){modal('Корректировка прошлого месяца','<p>'+escape(name('employees',employeeId))+' · '+day(date)+'</p>'+field('reason','Причина корректировки','','textarea',null,'required'),v=>api('times',{...b,...v}));return;}if(b.code==='О'&&D.user.role==='foreman'){requestForm(employeeId,'absence',date);input.value=old?.code||'';return;}if(old&&(['approved','pending'].includes(old.status)||new Date(old.createdAt||old.updatedAt||old.date).toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'})<D.today)){quickTimeForm(old.id,{actual:b.actual,code:b.code});toast('Укажите причину изменения; согласованная запись будет проверена повторно');return;}await api('times',b);input.defaultValue=value;await refresh();}catch(e){toast(e.message,true);input.value=old?(['В','О','Б','Н'].includes(old.code)?old.code:old.actual):'';}
