function timelineHtml(events){return events.length?`<div class="timeline">${events.map(r=>`<article class="event"><strong>${escape(r.title)} · ${escape(r.action)}</strong><p>${new Date(r.at).toLocaleString('ru-RU')} · ${escape(r.actor)}${r.effective?' · действует с '+day(r.effective):''}</p><p>${escape(r.reason||'')}</p>${r.changes.map(c=>`<div class="change"><span>${escape(c.field)}</span><span><del>${escape(c.before)}</del> → <ins>${escape(c.after)}</ins></span></div>`).join('')}</article>`).join('')}</div>`:empty('Изменений в этой категории пока нет');}
async function showTimeline(id){
 modal('Полная история сотрудника',`<h3>${escape(name('employees',id))}</h3><p>История за всё время учёта, независимо от месяца в верхней панели. Состав сведений определяется вашими правами.</p><div id="earnings-history"></div>${field('timelineCategory','Показать события','all','select',{all:'Вся хронология',requests:'Заявки на изменения',fleet:'Техника и ГСМ',assignment:'Перемещения по объектам и бригадам',salary:'Ставки и условия оплаты',earnings:'Начисления и удержания',payments:'Выплаты',time:'Табель и явка',bank:'Реквизиты',patent:'Патенты',status:'Статус и даты работы',documents:'Документы'})}<div id="full-timeline">Загрузка…</div><div id="timeline-more"></div>`,null);
 let cursor=null;const draw=async(append=false)=>{const category=$('[name=timelineCategory]').value,r=await api('employee-timeline?'+new URLSearchParams({id,category,...(append&&cursor?{cursor}:{} )}));if(!$('#full-timeline'))return;if(append)$('#full-timeline').insertAdjacentHTML('beforeend',timelineHtml(r.events));else $('#full-timeline').innerHTML=timelineHtml(r.events);cursor=r.nextCursor;$('#timeline-more').innerHTML=cursor?'<button type="button" class="btn" id="more-history">Показать ещё</button>':'';if(cursor)$('#more-history').onclick=()=>draw(true).catch(e=>toast(e.message,true));};$('[name=timelineCategory]').onchange=()=>draw().catch(e=>toast(e.message,true));await draw();
 if(seesSalary(id)){const rows=await api('employee-earnings?id='+encodeURIComponent(id));if($('#earnings-history'))$('#earnings-history').innerHTML='<h3>Заработок и выплаты по месяцам</h3>'+ (rows.length?table(['Месяц','Часы','Заработано','Компенсации','Удержания','К выдаче','Выплачено','Остаток'],rows.map(r=>[escape(r.period)+(r.closed?' · закрыт':''),num(r.hours),rub(r.accrued),rub(r.compensations),rub(r.deductions),rub(r.net),rub(r.paid),rub(r.balance)])):'<p>Начислений и выплат пока нет. Ставка в карточке сама по себе не является заработком.</p>');}
}
