async function requestUIAction(a,id){if(a==='group-transfer'){groupTransferForm(id);return true;}if(a==='request-new'){requestForm(id);return true;}if(!['request-detail','request-approve','request-return'].includes(a))return false;const r=D.employeeRequests.find(x=>x.id===id);if(!r)return true;if(a!=='request-detail'){modal(a==='request-approve'?'Подтвердить изменение':'Вернуть заявку',`<p>${escape(r.employeeName)} · ${escape(D.requestTypes[r.type])} · с ${day(r.effective)}</p>${field('reason','Комментарий проверяющего','','textarea',null,'required')}`,b=>api(r.members?'group-transfers/review':'employee-requests/review',{id,action:a==='request-approve'?'approve':'return',reason:b.reason}));return true;}
 if(r.members){modal(r.mode==='membership'?'Изменение состава бригады':'Групповой перевод',`<h3>${escape(r.employeeName)}</h3><p>${r.mode==='membership'?'В бригаду '+escape(r.brigadeName):escape(name('objects',r.sourceObjectId))+' → '+escape(name('objects',r.objectId))} · с ${day(r.effective)}</p><p>${badge(r.status)} · ${escape(r.reason)}</p><ul>${r.members.map(e=>'<li>'+escape(e.name)+'</li>').join('')}</ul>${r.canReview?button('Подтвердить изменение','request-approve',id,'primary')+button('Вернуть на исправление','request-return',id):''}`,null);return true;}
 const names={...fieldNames,payType:'Схема оплаты',rateMode:'Способ задания ставки',rate:'Стоимость часа, ₽',entityId:'Юрлицо',objectId:'Объект',brigadeId:'Бригада',code:'Отсутствие',to:'По дату',bank:'Банк',account:'Счёт',blocked:'Счёт заблокирован',bankConfirmed:'Реквизиты подтверждены',blockReason:'Причина блокировки',blockDocument:'Основание блокировки',status:'Статус',endDate:'Последний рабочий день',...D.requestFields};const val=(k,v)=>['objectId','brigadeId','entityId'].includes(k)?((k==='entityId'?D.entities:D.requestTargets[({objectId:'objects',brigadeId:'brigades'})[k]])?.find(x=>x.id===v)?.name||name(({objectId:'objects',brigadeId:'brigades',entityId:'entities'})[k],v)):typeof v==='boolean'?(v?'Да':'Нет'):statusLabels[v]||({hourly:'Почасовая оплата',explicit:'Ставка вручную','О':'Отпуск','Б':'Больничный','В':'Выходной','Н':'Отсутствует'})[v]||v;
 modal('Заявка на изменение',`<h3>${escape(r.employeeName)} · ${escape(D.requestTypes[r.type])}</h3><p>${badge(r.status)} · действует с ${day(r.effective)}</p><p>Подал: ${escape(r.createdBy)} · ${new Date(r.submittedAt).toLocaleString('ru-RU')}</p><dl class="definition">${Object.entries(r.proposed).map(([k,v])=>`<div><dt>${escape(names[k]||k)}</dt><dd>${r.before?escape(val(k,r.before[k])??'Не указано')+' → ':''}${escape(val(k,v))}</dd></div>`).join('')}</dl><p>Основание: ${escape(r.reason)}</p>${r.reviewedAt?`<p>Проверил: ${escape(r.reviewedBy)} · ${new Date(r.reviewedAt).toLocaleString('ru-RU')}<br>${escape(r.decisionReason)}</p>`:''}${r.canReview?button('Подтвердить изменение','request-approve',id,'primary')+button('Вернуть на исправление','request-return',id):''}<p class="form-help">При возврате подайте новую заявку с исправленными сведениями. Исходная останется в истории.</p>`,null);return true;}

function contactRows(){return (D.contacts||[]).filter(e=>(contactStatus==='all'||!['dismissed','left'].includes(e.status))&&(!contactCategory||e.category===contactCategory)&&(!contactDepartment||e.department===contactDepartment)&&(!contactSearch||[e.name,e.position,e.department,e.object,e.brigade,e.phone,e.email].join(' ').toLocaleLowerCase('ru').includes(contactSearch.toLocaleLowerCase('ru'))));}
function contactsPage(){if(!has('contacts.view'))return empty('Нет доступа к справочнику контактов');return heading('Контакты сотрудников','Общий справочник, включая АУП. Зарплаты и банковские реквизиты здесь не показываются.',has('export')?button('Скачать контакты в Excel','contacts-export','','','download'):'')+`<div class="filterbar"><input id="contact-search" type="search" aria-label="Поиск по контактам" placeholder="Имя, должность, телефон, отдел…" value="${escape(contactSearch)}"><select id="contact-category" aria-label="Категория персонала">${opts({workers:'Рабочие',aup:'АУП',unclassified:'Не уточнена'},contactCategory,'Все категории')}</select><select id="contact-department" aria-label="Подразделение">${opts([...new Set((D.contacts||[]).map(e=>e.department).filter(Boolean))].sort().map(x=>({id:x,name:x})),contactDepartment,'Все подразделения')}</select><select id="contact-status" aria-label="Состав справочника">${opts({active:'Текущие сотрудники',all:'Все, включая бывших'},contactStatus)}</select></div><div id="contact-list">${contactList()}</div>`;}
function contactList(){const rows=contactRows();const cols=['Сотрудник','Должность','Категория','Подразделение','Юрлицо','Объект','Бригада','Телефон','Почта'];return `<p class="muted">Найдено: ${rows.length}</p>${rows.length?`<div class="contact-journal" role="region" aria-label="Журнал контактов" tabindex="0"><table aria-label="Контакты сотрудников"><thead><tr>${cols.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${rows.map(e=>`<tr><th scope="row">${escape(e.name)}</th><td>${escape(e.position||'—')}</td><td>${({workers:'Рабочие',aup:'АУП'})[e.category]||'Не уточнена'}</td><td>${escape(e.department||'—')}</td><td>${escape(e.entity||'—')}</td><td>${escape(e.object||'—')}</td><td>${escape(e.brigade||'—')}</td><td>${e.phone?`<a href="tel:${escape(e.phone.replace(/[^+0-9]/g,''))}">${escape(e.phone)}</a>`:'—'}</td><td>${e.email?`<a href="mailto:${escape(encodeURIComponent(e.email))}">${escape(e.email)}</a>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Контакты не найдены')}`;}
function directDelete(kind,id,label){return id&&has('access.full')&&!previewUser?`<div class="actions direct-delete">${button(label,'delete-preview',kind+':'+id,'danger')}</div>`:'';}

function bindContacts(){for(const [id,set] of [['contact-search',v=>contactSearch=v],['contact-category',v=>contactCategory=v],['contact-department',v=>contactDepartment=v],['contact-status',v=>contactStatus=v]]){const el=$('#'+id);if(el)el.addEventListener(id==='contact-search'?'input':'change',()=>{set(el.value);$('#contact-list').innerHTML=contactList();});}}
function updatesPage(){return heading('Обновления','Что изменилось в программе — коротко и по делу')+(has('access.full')?`<section class="card"><div class="card-body"><h2>Обслуживание сервиса</h2><p>Перед обновлением включите обслуживание: пользователи увидят предупреждение, сохранение будет приостановлено. После проверки новой версии выключите его.</p><div class="actions">${button('Включить обслуживание','maintenance-on')}${button('Завершить обслуживание','maintenance-off')}</div></div></section>`:'')+(D.releases||[]).map(r=>`<section class="card release-card"><div class="card-body"><p class="muted">${day(r.date)} · Версия ${escape(r.version)}</p><h2>${escape(r.title)}</h2><ul>${r.items.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></div></section>`).join('');}
async function directoryAction(a,id){if(a==='employee-privacy'){const e=entity('employees',id);modal('Доступ к зарплате: '+e.name,`<div class="form-grid">${field('staffCategory','Категория персонала',e.staffCategory||'unclassified','select',{unclassified:'Не уточнена',workers:'Рабочие',aup:'АУП'})}${field('salaryPrivate','Скрыть зарплату — видна только с полными правами',e.salaryPrivate,'checkbox')}${field('reason','Основание изменения','','text',null,'required')}<p class="form-help">Ограничение действует сразу на все связанные оформления человека и распространяется на историю, отчёты и выгрузки. Суммы начислений и закрытые периоды не пересчитываются.</p></div>`,b=>api('employee-privacy',{id,...b}));return true;}if(a==='contacts-export'){const q=new URLSearchParams({kind:'contacts',search:contactSearch,category:contactCategory,department:contactDepartment,status:contactStatus});if(previewUser)q.set('viewAs',previewUser);window.open('./api/export?'+q,'_blank');return true;}if(a==='maintenance-on'||a==='maintenance-off'){if(a==='maintenance-on'){modal('Включить обслуживание','<p>Сохранение данных будет временно заблокировано для всех пользователей. Открытые формы останутся на экране.</p>',async()=>{serviceState=await api('maintenance',{active:true});paintServiceStatus();},'Включить');}else{serviceState=await api('maintenance',{active:false});paintServiceStatus();toast('Обслуживание завершено. Можно сохранять данные.');}return true;}if(a==='reload-version'){location.reload();return true;}return false;}
function paintServiceStatus(){let banner=$('#service-status');if(!banner){banner=document.createElement('div');banner.id='service-status';banner.setAttribute('role','status');document.body.append(banner);}banner.hidden=!serviceState.active&&!serviceVersionChanged;banner.className='service-status';banner.innerHTML=serviceState.active?escape(serviceState.message||'Идёт обновление. Сохранение временно приостановлено.'):`Доступна новая версия. Сначала сохраните или скопируйте введённые данные, затем обновите страницу. ${button('Обновить страницу','reload-version')}`;const dialog=$('#dialog');let note=$('#dialog-service-status');if(dialog?.open){if(!note){note=document.createElement('p');note.id='dialog-service-status';note.className='notice-banner';dialog.prepend(note);}note.hidden=!serviceState.active;note.textContent=serviceState.active?'Идёт обновление. Сохранение временно приостановлено. Не закрывайте форму.':'';}}
async function pollService(){try{const r=await fetch('./api/service-status',{cache:'no-store'});if(!r.ok)return;const data=await r.json();serviceState=data;serviceVersionChanged=data.version!==currentVersion;paintServiceStatus();}catch{/* During a restart keep the current form and last maintenance warning. */}}
setInterval(pollService,5000);pollService();

async function recoveryAction(a){
 if(a==='recovery-open'){recoveryToken='';modal('Перенос рабочей базы',`<p>Выберите подготовленный файл .mayak.json. Обычный Excel или архив SQLite здесь не подходит. Сначала программа проверит файл и текущую базу.</p><input type="file" id="recovery-file" accept=".json" aria-label="Файл рабочей базы">${button('Проверить перенос','recovery-check','','primary')}<div id="recovery-result" role="status"></div>`,null);return true;}
 if(a==='recovery-check'){recoveryToken='';$('#recovery-result').textContent='Проверка…';const f=$('#recovery-file').files[0];if(!f)throw Error('Выберите файл');if(f.size>12*1024*1024)throw Error('Файл больше 12 МБ');const p=JSON.parse(await f.text());const r=await api('recovery/preview',{package:p});recoveryToken=r.token;$('#recovery-result').innerHTML=`<h3>Готово к переносу</h3><p>Сотрудники: ${r.counts.employees}. Объекты: ${r.counts.objects}. Бригады: ${r.counts.brigades}. Записи табеля: ${r.counts.times}. История: ${r.audit} записей и ${r.versions} версий.</p><p>Сохранятся нынешние пользователи: ${r.users}. Перед переносом автоматически создаётся резервная копия. Иванов, Абдула и учебные записи будут удалены из действующей базы.</p>${r.warnings.map(w=>'<p>'+escape(w)+'</p>').join('')}<label>Для подтверждения введите ПЕРЕНЕСТИ<input id="recovery-confirm" autocomplete="off"></label>${button('Выполнить перенос','recovery-commit','','primary')}`;return true;}
 if(a==='recovery-commit'){const el=$('[data-action="recovery-commit"]');if(el)el.disabled=true;try{const r=await api('recovery/commit',{token:recoveryToken,confirm:$('#recovery-confirm').value});recoveryToken='';$('#recovery-result').innerHTML=`<h3>Перенос завершён</h3><p>Карточек: ${r.employees}. Пользователи и пароли сохранены.</p><p>Копия прежней базы: ${escape(r.backup)}</p>`;await refresh();}finally{if(el)el.disabled=false;}return true;}
 return false;
}

async function deletionAction(a,id){
 if(a==='delete-center'){const d=await api('admin-delete');modal('Удаление данных и корзина',`<p>Только для пользователей с полными правами. Связанные записи нужно сначала перепривязать или удалить. Пользователи удаляются в разделе «Пользователи». История действий, настройки и закрытые расчёты защищены.</p><input id="deletion-search" placeholder="Найти запись" aria-label="Поиск записей"><div id="deletion-rows"></div><h3>Корзина</h3>${table(['Раздел','Запись','Дата',''],d.trash.map(r=>[escape(d.kinds[r.kind]),escape(r.name),day(r.at),button('Восстановить','delete-restore',r.id)]))}`,null);const draw=()=>{const q=$('#deletion-search').value.toLowerCase();$('#deletion-rows').innerHTML=table(['Раздел','Запись',''],d.records.filter(r=>(d.kinds[r.kind]+' '+r.name).toLowerCase().includes(q)).map(r=>[escape(d.kinds[r.kind]),escape(r.name),button('Удалить','delete-preview',r.kind+':'+r.id,'danger small')]));};$('#deletion-search').addEventListener('input',draw);draw();return true;}
 if(a==='delete-preview'){const split=id.indexOf(':'),kind=id.slice(0,split),key=id.slice(split+1),p=await api('admin-delete/preview',{kind,id:key});if(p.dependencies.length&&!p.canDetach){modal('Есть связанные записи',`<p>Перед удалением ${escape(p.name)} измените привязки или удалите следующие записи:</p>${table(['Раздел','Запись'],p.dependencies.map(r=>[escape(r.section),escape(r.name)]))}`,null);}else modal('Удаление в корзину',`<p>Удалить ${escape(p.name)}? Запись исчезнет из рабочих разделов. Её можно будет восстановить. История сохранится.</p>${p.canDetach?'<p>Связанные сотрудники останутся без текущего назначения. При удалении объекта его бригады останутся без объекта. Старые часы и привязки в истории сохранятся. После восстановления текущие назначения нужно заполнить заново.</p>'+table(['Связанные данные','Запись'],p.dependencies.map(r=>[escape(r.section),escape(r.name)])):''}${field('reason','Причина *','','textarea',null,'required')}`,b=>api('admin-delete/commit',{kind,id:key,confirm:key,detach:p.canDetach,reason:b.reason}),'Удалить');return true;}
 if(a==='delete-restore'){modal('Восстановление записи',field('reason','Причина *','','textarea',null,'required'),b=>api('admin-delete/restore',{id,reason:b.reason}),'Восстановить');return true;}return false;
}

function brigadeObjects(id){const counts=new Map();for(const e of D.employees.filter(e=>e.brigadeId===id)){const key=e.objectId||'';counts.set(key,(counts.get(key)||0)+1);}const rows=[...counts].sort(([a],[b])=>name('objects',a).localeCompare(name('objects',b),'ru'));if(!rows.length)return 'Пока нет назначений';if(rows.length===1)return escape(name('objects',rows[0][0]));return '<details class="brigade-objects"><summary>Объекты / назначения: '+rows.length+'</summary><ul>'+rows.map(([id,count])=>'<li>'+escape(name('objects',id))+' — '+count+' чел.</li>').join('')+'</ul></details>';}
function brigadesDirectory(){return `<section class="card" style="margin-top:24px"><div class="card-head"><h2>Все бригады</h2></div><p class="card-body">Одна бригада может работать на нескольких объектах. Ниже указаны текущие объекты её сотрудников. <a href="#knowledge/transfer">Как назначить объект сотрудникам бригады</a>. Переименование сохраняется с датой и основанием.</p>${table(['Бригада','Объекты сотрудников','Сотрудников','Действия'],D.brigades.map(b=>[escape(b.name),brigadeObjects(b.id),D.employees.filter(e=>e.brigadeId===b.id).length,(has('employees.edit')?button('Добавить сотрудников','brigade-members',b.id,'small')+button('Перевести сотрудников','group-transfer',b.id,'small'):'')+(has('settings.edit')?button('Изменить название','brigade-rename',b.id,'small')+button('Настройки бригады','reference-edit','brigades:'+b.id,'small')+button('История','reference-history','brigades:'+b.id,'small'):'')+(has('access.full')&&!previewUser?button('Удалить бригаду','delete-preview','brigades:'+b.id,'danger small'):'')]))}</section>`;}
function assignmentNoticeDialog(){const rows=D.assignmentNotices||[];modal('Уведомления',locationNoticeList()+`<h3>Объект и бригада не назначены</h3><p>Текущие сотрудники, у которых не назначен объект или бригада. Для сотрудников категории АУП объект и бригада необязательны, поэтому они не включены. После заполнения уведомление исчезнет.</p>${rows.length?table(['Сотрудник','Нужно заполнить','Действие'],rows.map(n=>[escape(n.name),n.missing.map(escape).join('<br>'),has('employees.edit')?button('Назначить объект / бригаду','transfer',n.employeeId):D.canRequest?button('Подать заявку','request-new',n.employeeId):button('Открыть карточку','employee-detail',n.employeeId)])):empty('Все назначения заполнены')}`,null);}
function groupTransferForm(brigadeId){
 modal(has('employees.edit')?'Перевести сотрудников бригады':'Заявка на перевод бригады',`<div class="form-grid">${field('brigadeId','Бригада',brigadeId||D.brigades[0]?.id,'select',D.brigades)}${field('sourceObjectId','С какого объекта','','select',[])}${field('objectId','На какой объект','','select',[{id:'',name:'Выберите объект'},...objectOptions(D.requestTargets.objects,D.today)],'required')}${field('effective','Дата перевода',D.today,'date',null,'required')}${field('reason','Общее основание','','textarea',null,'required')}</div><p>Все сотрудники выбранной бригады на исходном объекте отмечены автоматически. Снимите отметку с тех, кто остаётся. Бригада и юрлицо каждого сохраняются.</p><div id="group-members"></div>`,b=>api('group-transfers',{brigadeId:b.brigadeId,sourceObjectId:b.sourceObjectId,objectId:b.objectId,effective:b.effective,reason:b.reason,employeeIds:[...$('#group-members').querySelectorAll('input:checked')].map(x=>x.value)}),has('employees.edit')?'Перевести выбранных':'Отправить одну заявку');
 const people=()=>D.employees.filter(e=>e.brigadeId===$('[name=brigadeId]').value&&['active','unknown'].includes(e.status));
 const draw=()=>{const es=people().filter(e=>(e.objectId||'')===$('[name=sourceObjectId]').value);const root=$('#group-members');root.innerHTML='<div class="group-selection-tools"><button type="button" class="btn" id="group-select-all">Выбрать всех</button><button type="button" class="btn" id="group-clear-all">Снять все</button><span id="group-selection-count" aria-live="polite"></span></div><div class="group-member-list">'+es.map(e=>`<label class="group-member-row"><input type="checkbox" checked value="${escape(e.id)}"><span>${escape(e.name)}</span></label>`).join('')+'</div>';const update=()=>{$('#group-selection-count').textContent='Выбрано: '+root.querySelectorAll('input:checked').length+' из '+es.length;};const select=value=>{root.querySelectorAll('input[type=checkbox]').forEach(el=>el.checked=value);update();};$('#group-select-all').onclick=()=>select(true);$('#group-clear-all').onclick=()=>select(false);root.onchange=update;update();};
 const source=()=>{const ids=[...new Set(people().map(e=>e.objectId||''))];$('[name=sourceObjectId]').innerHTML=opts(ids.map(id=>({id,name:name('objects',id)})),ids[0]||'');draw();};$('[name=brigadeId]').onchange=source;$('[name=sourceObjectId]').onchange=draw;source();
}

function closedObjectsList(){const rows=D.objects.filter(o=>closedObject(o,D.today));return '<details class="card"><summary>Завершённые объекты ('+rows.length+')</summary>'+table(['Объект',''],rows.map(o=>[escape(o.name),has('settings.edit')?button('Настроить','reference-edit','objects:'+o.id):'']))+'</details>';}

document.addEventListener('change',ev=>{if(ev.target.matches('[data-time-select]')){const id=ev.target.dataset.timeSelect;if(ev.target.checked)chosenTimeEmployees.add(id);else chosenTimeEmployees.delete(id);$('#time-selected-count').textContent='Выбрано: '+chosenTimeEmployees.size;}});
document.addEventListener('input',ev=>{if(ev.target.matches('[data-time-scroll]')){const wrap=$('.time-table')?.closest('.table-wrap');if(wrap)wrap.scrollLeft=(wrap.scrollWidth-wrap.clientWidth)*Number(ev.target.value)/100;}});
function printTimeSelection(){const es=visibleTimeEmployees().filter(e=>!chosenTimeEmployees.size||chosenTimeEmployees.has(e.id));if(!es.length){toast('Выберите сотрудников для печати',true);return;}const bounds=timeRange||monthBounds(period),dates=rangeDays(bounds.from,bounds.to),rows=gridTimes(D.times,timeFilters()).filter(t=>t.date>=bounds.from&&t.date<=bounds.to);const area=document.createElement('section');area.id='print-roster';for(let start=0;start<dates.length;start+=14){const ds=dates.slice(start,start+14);area.innerHTML+='<section class="print-time-sheet"><h1>Табель рабочего времени</h1><p>'+day(bounds.from)+' — '+day(bounds.to)+' · '+(objectFilter?escape(name('objects',objectFilter)):'Все объекты')+' · '+(brigadeFilter?escape(name('brigades',brigadeFilter)):'Все бригады')+'</p><p>Дни на листе: '+day(ds[0])+' — '+day(ds.at(-1))+'</p>'+table(['Сотрудник',...ds.map(day),'Итого за период'],es.map(e=>[escape(e.name),...ds.map(dt=>{const ts=rows.filter(t=>t.employeeId===e.id&&t.date===dt);return ts.length?ts.some(t=>t.actual>0)?num(ts.reduce((a,t)=>a+t.actual,0)):ts.map(t=>escape(t.code)).join(', '):'—';}),num(rows.filter(t=>t.employeeId===e.id).reduce((a,t)=>a+t.actual,0))]))+'</section>';}document.querySelector('#print-roster')?.remove();document.body.append(area);window.addEventListener('afterprint',()=>area.remove(),{once:true});window.print();}



function locationSettingsPage(){const ids=D.locationNoticeSettings?.recipients||[],mail=D.mailStatus||{};return '<section class="card"><div class="card-body"><h2>Уведомления о переводах между объектами</h2><p>Получатели: '+(ids.map(id=>escape(name('users',id))).join(', ')||'Не назначены')+'</p><p>Учитывается область доступа каждого получателя. В письме будет ссылка на сервис без кадровых и финансовых данных.</p><p><strong>Почта: '+(mail.configured?'параметры отправки заданы':'отправка не подключена')+'</strong></p>'+(mail.error?'<p class="form-error">'+escape(mail.error)+'</p>':'')+(mail.lastSentAt?'<p>Последняя передача письма почтовому серверу: '+escape(new Date(mail.lastSentAt).toLocaleString('ru-RU'))+'</p>':'')+'<p>Для подключения программисту нужны почтовый сервер, порт, логин, пароль приложения и адрес отправителя. Пароль хранится только на сервере, не в карточках и не в GitHub.</p>'+button('Получатели и почта','location-settings')+'</div></section>';}
function locationSettingsForm(){const c=D.locationNoticeSettings||{},ids=c.recipients||[],manage=has('users.edit');modal('Получатели и почта уведомлений','<p>Отметьте пользователей. По желанию укажите каждому адрес для писем. Получатель увидит подробности после входа в свою учётную запись.</p><div class="recipient-list">'+D.users.filter(u=>u.active).map(u=>'<div class="recipient-row"><label><input type="checkbox" name="recipient:'+escape(u.id)+'" '+(ids.includes(u.id)?'checked':'')+'><span>'+escape(u.name)+'</span></label>'+(manage?field('mail:'+u.id,'Почта — '+u.name,c.emails?.[u.id]||'','email'):'')+'</div>').join('')+'</div>'+(manage?field('emailEnabled','Отправлять уведомления на почту',c.emailEnabled,'checkbox',null,D.mailStatus?.configured?'':'disabled'):'')+(!D.mailStatus?.configured?'<p>Адреса можно сохранить сейчас. Включить отправку можно после подключения почты программистом.</p>':'')+'<p>Письма начнут отправляться по новым переводам после включения. Проверка очереди — раз в минуту. Если почтовый сервер недоступен, сервис повторит попытку.</p>',b=>api('location-notices/settings',{recipients:Object.keys(b).filter(k=>k.startsWith('recipient:')&&b[k]).map(k=>k.slice(10)),...(manage?{emails:Object.fromEntries(Object.keys(b).filter(k=>k.startsWith('mail:')).map(k=>[k.slice(5),b[k]])),emailEnabled:D.mailStatus?.configured?b.emailEnabled:!!c.emailEnabled}:{})}));}
function locationNoticeList(){const rows=D.locationNotices||[];return rows.length?'<h3>Переводы между объектами</h3><p>Проверьте документы сотрудника для нового места работы. Дата перевода может быть будущей. Здесь показываются до 200 непрочитанных уведомлений.</p>'+table(['Сотрудник','Перевод','Патент',''],rows.map(n=>[escape(n.name),escape(n.from)+' → '+escape(n.to)+'<br>С '+day(n.effective)+'<br>'+escape(n.actor),escape(n.patent||'Не указан')+'<br>'+escape([n.patentRegion,n.patentDistrict].filter(Boolean).join(', '))+(n.patentIssued?'<br>Выдан: '+day(n.patentIssued):'')+(n.patentEnd?'<br>До: '+day(n.patentEnd):''),button('Прочитано','location-read',n.id,'small')])):'';}

function brigadeMembersForm(brigadeId){const people=D.employees.filter(e=>e.brigadeId!==brigadeId&&['active','unknown'].includes(e.status));modal('Добавить сотрудников в бригаду '+name('brigades',brigadeId),'<p>Выбранные сотрудники перейдут в эту бригаду. Объект и юрлицо каждого сохранятся.</p>'+field('effective','Дата изменения',D.today,'date',null,'required')+field('reason','Основание','','textarea',null,'required')+'<label>Найти сотрудника<input type="search" id="member-search"></label><div class="group-selection-tools"><button type="button" class="btn" id="members-all">Выбрать найденных</button><button type="button" class="btn" id="members-none">Снять все</button></div><div class="recipient-list" id="membership-list">'+people.map(e=>'<label data-member-name="'+escape(e.name.toLocaleLowerCase('ru'))+'"><input type="checkbox" value="'+escape(e.id)+'"><span>'+escape(e.name)+' · '+escape(name('brigades',e.brigadeId)||'Без бригады')+'</span></label>').join('')+'</div>',b=>api('group-transfers',{mode:'membership',brigadeId,effective:b.effective,reason:b.reason,employeeIds:[...$('#membership-list').querySelectorAll('input:checked')].map(x=>x.value)}));$('#member-search').oninput=ev=>$$('#membership-list label').forEach(row=>row.hidden=!row.dataset.memberName.includes(ev.target.value.toLocaleLowerCase('ru')));$('#members-all').onclick=()=>$$('#membership-list label').filter(row=>!row.hidden).forEach(row=>row.querySelector('input').checked=true);$('#members-none').onclick=()=>$$('#membership-list input').forEach(input=>input.checked=false);}

document.addEventListener('scroll',ev=>{if(ev.target?.matches?.('.table-wrap')&&ev.target.querySelector('.time-table')){const slider=$('[data-time-scroll]'),w=ev.target;if(slider)slider.value=w.scrollWidth>w.clientWidth?100*w.scrollLeft/(w.scrollWidth-w.clientWidth):0;}},true);

function historyValue(k,v,kind){return readableHistory(k,v,{kind,resolve:(type,id)=>entity(type,id)?.name});}

function groupEmployeeRows(rows){const groups=new Map();for(const e of rows){const id=e.personId||e.id;if(!groups.has(id))groups.set(id,[]);groups.get(id).push(e);}return [...groups.values()].map(es=>es.find(e=>e.id===e.timeOwnerId)||es[0]);}
function personEmployments(e){return e.personId?D.employees.filter(x=>x.personId===e.personId):[e];}
function employmentSummary(e){return personEmployments(e).map(x=>escape(x.employment)+' · '+escape(name('entities',x.entityId))).join('<br>');}
function unifiedEmployeeDetail(id){const e=entity('employees',id),es=personEmployments(e),main=es.find(x=>x.id===x.timeOwnerId)||e;modal('Карточка сотрудника', '<h2>'+escape(main.name)+'</h2><p>Один человек — '+es.length+' доступных оформлений. Часы и явка вводятся один раз по основному оформлению. История и выплаты каждого оформления сохраняются отдельно.</p><p class="notice-banner">Расчёт зарплаты по нескольким оформлениям ещё не настроен. Новые общие часы не создают автоматических начислений.</p>'+'<div class="employment-summary">'+table(['Юрлицо','Оформление','Табельный номер','Учёт',''],es.map(x=>[escape(name('entities',x.entityId)),escape(x.employment),escape(x.code),x.id===x.timeOwnerId?'Общий табель':'Дополнительное оформление',button('Открыть оформление','employment-detail',x.id)+button('История','employee-history',x.id)]))+'</div>'+(has('access.full')?button('Добавить ещё оформление','profile-link',e.id)+button('Разделить оформления','profile-unlink',e.personId):''),null);}
function profileLinkForm(id){const e=entity('employees',id),candidates=D.employees.filter(x=>!x.personId||x.personId===e.personId);modal('Одна карточка — несколько оформлений','<p>Выберите оформления одного и того же человека. Нельзя объединять разных людей только из-за одинакового ФИО. История не удаляется. Изменение действует с сегодняшнего дня; новые общие часы пока не участвуют в автоматическом расчёте.</p><label>Найти оформление<input type="search" id="profile-search" placeholder="ФИО или табельный номер"></label><div class="recipient-list" id="profile-members">'+candidates.map(x=>'<label><input type="checkbox" value="'+escape(x.id)+'" '+(x.id===id||(e.personId&&x.personId===e.personId)?'checked':'')+'><span>'+escape(x.name)+' · '+escape(x.code)+' · '+escape(name('entities',x.entityId))+' · '+escape(x.employment)+'</span></label>').join('')+'</div>'+field('primaryId','Основное оформление для общего табеля',e.timeOwnerId||id,'select',candidates.map(x=>({id:x.id,name:x.name+' · '+x.code+' · '+name('entities',x.entityId)})))+field('samePerson','Подтверждаю: это один и тот же человек',false,'checkbox')+field('reason','Основание объединения','','textarea',null,'required'),b=>api('employee-profiles/link',{...b,profileId:e.personId,employeeIds:[...$('#profile-members').querySelectorAll('input:checked')].map(x=>x.value)}));$('#profile-search').oninput=ev=>$$('#profile-members label').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase('ru').includes(ev.target.value.toLocaleLowerCase('ru')));}

function employeeFormTabs(){
 const form=$('#modal-form'),grid=$('.form-grid',form),body=$('.dialog-body',form);if(!grid)return;
 const groups=[['Основное',new Set(['Основные данные','Оформление и место работы','Реквизиты и блокировка'])],['Смена и оплата',new Set(['Договоренности о смене','Оплата'])],['Патенты и документы',new Set(['Отъезд и возвращение','РКЛ — отдельная проверка','Миграционные данные'])],['Контакты',new Set(['Контакты'])]];
 const nav=document.createElement('div');nav.className='employee-card-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Разделы карточки');
 const panels=groups.map(([title],i)=>{const p=document.createElement('div');p.className='form-grid employee-card-panel';p.id='employee-panel-'+i;p.setAttribute('role','tabpanel');const b=document.createElement('button');b.type='button';b.textContent=title;b.id='employee-tab-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls',p.id);p.setAttribute('aria-labelledby',b.id);b.onclick=()=>show(i);nav.append(b);return p;});
 const common=document.createElement('div');common.className='form-grid employee-card-common';let target=panels[0];for(const node of [...grid.children]){if(node.classList.contains('form-section')){const title=node.textContent.trim();target=title==='Дата и основание изменения'?common:panels[Math.max(0,groups.findIndex(([,titles])=>titles.has(title)))];}target.append(node);}
 const heading=panels[0].firstElementChild;let previous=heading;for(const key of ['name','code','position','status']){const field=form.elements[key]?.closest('.field');if(field){previous.after(field);previous=field;}}grid.before(nav,...panels,common);grid.remove();
 for(const hint of $$('.field>small.form-help',form)){const help=document.createElement('details');help.className='field-explanation';const summary=document.createElement('summary');summary.textContent='Как заполнить';help.append(summary);hint.replaceWith(help);help.append(hint);}
 function show(i){panels.forEach((p,n)=>{p.hidden=n!==i;nav.children[n].setAttribute('aria-selected',String(n===i));});body.scrollTop=0;}
 form.addEventListener('invalid',ev=>{const index=panels.findIndex(p=>p.contains(ev.target));if(index>=0)show(index);},true);show(0);
}

async function employeeDetailContent(id){await rawEmployeeDetailContent(id);const body=$('.dialog-body'),dl=$('.definition',body);if(!dl)return;const nav=document.createElement('div');nav.className='employee-card-tabs';nav.setAttribute('role','tablist');const panels=['Основное','Прочие сведения','Документы и история'].map((title,i)=>{const panel=document.createElement('section');panel.setAttribute('role','tabpanel');const b=document.createElement('button');b.type='button';b.textContent=title;b.setAttribute('role','tab');b.onclick=()=>show(i);nav.append(b);return panel;});const main=document.createElement('dl'),other=document.createElement('dl');main.className=other.className='definition';for(const item of [...dl.children]){const key=item.querySelector('dt')?.textContent||'';(/Юрлицо|Объект|Бригада|Оформление|занятости|договор|Договор|Реквизит|реквизит|Прием|приёма|Табельный|ФИО|Должность|банк|Банк|Счет|счёт|БИК|карты|Получатель|SWIFT/i.test(key)?main:other).append(item);}panels[0].append(main);panels[1].append(other);let next=dl.nextSibling;while(next){const following=next.nextSibling;panels[2].append(next);next=following;}dl.replaceWith(nav,...panels);function show(i){panels.forEach((p,n)=>{p.hidden=i!==n;nav.children[n].setAttribute('aria-selected',String(i===n));});body.scrollTop=0;}show(0);}
